var $ = function(s,r){return (r||document).querySelector(s)};
function esc(s){var d=document.createElement("div");d.textContent=s==null?"":String(s);return d.innerHTML}
function load(k,def){try{var v=localStorage.getItem("sm_"+k);return v?JSON.parse(v):def}catch(e){return def}}
function save(k,v){try{localStorage.setItem("sm_"+k,JSON.stringify(v))}catch(e){}}
function toast(msg){var t=document.createElement("div");t.className="toast";t.textContent=msg;document.body.appendChild(t);setTimeout(function(){t.remove()},2400)}
