var I={arrow:ion("arrow",16),pin:ion("pin",16),heart:ion("heart",20),rain:ion("rain",20),search:ion("search",18),check:ion("check",12),bus:ion("bus",17),chev:ion("chev",16),
 person:'<img src="img/s/avatar.webp" alt="" style="width:100%;height:100%;object-fit:cover">'};
function ic(n,s){return ion(n,s||26)}
var P={search:"search",cloud:"cloud",lang:"lang",heart:"heart",pin:"pin",star:"star",globe:"globe",bus:"bus",sun:"sun",ok:"ok",shop:"shop",mega:"mega"};

/* ---------- accounts ----------
   AUTH runs on this browser's storage in the preview. After you add Firebase:
   1) load the Firebase compat SDKs (firebase-app-compat.js, firebase-auth-compat.js) and call firebase.initializeApp(yourConfig)
   2) set AUTH_PROVIDER = "firebase"
   Email/password and Google sign-in then go through Firebase; trip details (name, starting location,
   saved places) stay in the profile record below, keyed by email. */
var AUTH_PROVIDER = (window.firebase && (FIREBASE_HOSTS.indexOf(location.hostname) > -1 || /\.github\.io$/.test(location.hostname))) ? "firebase" : "local";
var users = load("users",{});
var session = load("session",null);
function me(){return session && users[session] ? users[session] : null}
function ensureProfile(email,name){
  email=email.toLowerCase();
  if(!users[email])users[email]={name:name||email.split("@")[0],email:email,start:"",gender:"",phone:"",favs:[],photo:""};
  save("users",users);return users[email];
}
function startSession(email){session=email.toLowerCase();save("session",session);renderAuth()}
function fb(){return AUTH_PROVIDER==="firebase"&&window.firebase&&firebase.auth?firebase.auth():null}
var AUTH={
  signUp:async function(name,email,pw){
    email=email.toLowerCase();
    var f=fb();
    if(f){var c=await f.createUserWithEmailAndPassword(email,pw);if(c.user.updateProfile)await c.user.updateProfile({displayName:name})}
    else{if(users[email]&&users[email].pw)throw {code:"exists"};}
    var u=ensureProfile(email,name);u.name=name;if(!f)u.pw=pw;save("users",users);startSession(email);return u;
  },
  signIn:async function(email,pw){
    email=email.toLowerCase();
    var f=fb();
    if(f){await f.signInWithEmailAndPassword(email,pw);ensureProfile(email)}
    else if(!users[email]||users[email].pw!==pw)throw {code:"bad"};
    startSession(email);return users[email];
  },
  google:async function(){
    var f=fb();
    if(!f)throw {code:"no_firebase"};
    var c=await f.signInWithPopup(new firebase.auth.GoogleAuthProvider());
    ensureProfile(c.user.email,c.user.displayName);startSession(c.user.email);return users[c.user.email.toLowerCase()];
  },
  signOut:async function(){var f=fb();if(f)await f.signOut();session=null;save("session",null);renderAuth()},
  reset:async function(email){var f=fb();if(!f)throw {code:"no_firebase_reset"};await f.sendPasswordResetEmail(email.toLowerCase())}
};
function authError(e){
  var c=e&&e.code||"";
  if(c==="exists"||c==="auth/email-already-in-use")return "An account with this email already exists. Log in instead.";
  if(c==="bad"||c==="auth/wrong-password"||c==="auth/user-not-found"||c==="auth/invalid-credential")return "That email and password don’t match an account. Check them or sign up.";
  if(c==="no_firebase")return "Google sign-in turns on once Firebase is connected.";
  if(c==="auth/popup-closed-by-user")return "Google sign-in was closed before it finished.";
  if(c==="no_firebase_reset")return "Password reset works on the live site once Firebase is connected.";
  if(c==="auth/invalid-email")return "Enter a valid email address.";
  if(c==="auth/too-many-requests")return "Too many attempts. Wait a few minutes and try again.";
  if(c==="auth/unauthorized-domain")return "This domain isn’t allowed for sign-in yet. Add it under Authentication → Settings → Authorized domains.";
  if(c==="auth/weak-password")return "Use a password with at least 6 characters.";
  return "Something went wrong. Try again in a moment.";
}
var DEMO={email:"demo@seoulmate.travel",pw:"seoul1234"};
function seedDemo(){
  if(AUTH_PROVIDER!=="local")return;
  if(!users[DEMO.email]){users[DEMO.email]={name:"Demo Traveler",email:DEMO.email,pw:DEMO.pw,start:"Myeongdong Station",gender:"",phone:"",favs:["Changdeokgung Palace","N Seoul Tower","Itaewon Street"],photo:""};save("users",users)}
}
seedDemo();
/* keep the header in sync with Firebase's real login state */
/* Profiles and saved places live in Firestore at users/{uid} when Firebase is on; this browser keeps a cached copy. */
var FIELDS=["name","email","start","gender","phone","favs","photo"];
function db(){return fb()&&firebase.firestore?firebase.firestore():null}
function persist(u){
  u=u||me();save("users",users);
  var d=db(),cu=fb()&&fb().currentUser;
  if(!d||!u||!cu)return Promise.resolve();
  var out={updatedAt:firebase.firestore.FieldValue.serverTimestamp()};FIELDS.forEach(function(k){out[k]=u[k]==null?"":u[k]});
  return d.collection("users").doc(cu.uid).set(out,{merge:true}).catch(function(){toast("Couldn’t save to your account. Check your connection.")});
}
async function pullProfile(user){
  var email=user.email.toLowerCase(),u=ensureProfile(email,user.displayName),d=db();
  if(!d)return u;
  try{
    var snap=await d.collection("users").doc(user.uid).get();
    if(snap.exists){var data=snap.data();FIELDS.forEach(function(k){if(data[k]!=null&&data[k]!=="")u[k]=data[k]});save("users",users)}
    else{await persist(u)}
  }catch(e){}
  return u;
}
if(fb()){fb().onAuthStateChanged(async function(user){
  if(user&&user.email){await pullProfile(user);session=user.email.toLowerCase();save("session",session);renderAuth();route()}
  else if(session){session=null;save("session",null);renderAuth();route()}
})}
function favs(){var u=me();return u?(u.favs||[]):[]}
function setFavs(list){var u=me();if(!u)return;u.favs=list;persist(u)}
function isFav(n){return favs().indexOf(n)>-1}
function toggleFav(n){
  if(!me()){toast("Log in to save places to your itinerary");go("login");return false}
  var f=favs().slice(),i=f.indexOf(n);if(i>-1)f.splice(i,1);else f.push(n);setFavs(f);return f.indexOf(n)>-1;
}

function renderAuth(){
  var html = me()
   ? '<a class="btn fill" href="#profile">Profile</a>'
   : '<a class="btn line" href="#signup">Sign Up</a><a class="btn fill" href="#login">Login</a>';
  $("#auth").innerHTML=html;$("#auth2").innerHTML=html;if(typeof fixLinks==="function"&&typeof ROUTES!=="undefined"){fixLinks($("#auth"));fixLinks($("#auth2"))}
}

