   REPORTS.map(function(r,i){
     return '<div class="smr-card" tabindex="0" role="button" data-rep="'+i+'"><div class="smr-img"><img src="'+REPORT_PAGES[r.k][0]+'" alt="'+esc(r.ko)+' report cover" loading="lazy"><span class="sent"><i>'+I.check+'</i>Sent</span></div>'+
      '<div class="bd"><h3>'+esc(r.title)+'</h3><p>'+esc(r.desc)+'</p><div class="meta">Oct 2026 · '+r.reviews+' reviews · '+r.pages+' pages</div><span class="link">View report '+I.arrow+'</span></div></div>'}).join("")+
   '</div></section>';
