function profilePage(){
  var u=me();
  return shell('<form class="panel" id="pForm" novalidate>'+tabs("p")+
   '<div class="who"><div class="pav">'+avatarHtml(u)+'<label for="pPhoto" title="Change photo">'+ion("pencil",14)+'</label><input type="file" id="pPhoto" accept="image/*" aria-label="Change photo"></div>'+
   '<div style="min-width:0"><h1>'+esc(u.name)+'</h1><p>'+esc(u.email)+'</p>'+(u.photo?'<button type="button" class="rm" id="pRm">Remove photo</button>':'')+'</div></div>'+
   '<div class="grp trip"><h2>Your trip</h2><div class="fld"><label for="pStart">Place you are staying / Starting location (address)<em>*</em></label><input class="in" id="pStart" value="'+esc(u.start)+'" placeholder="e.g. Myeongdong Station or your hotel address"><span class="hint">Routes in your itinerary start from here.</span></div></div>'+
   '<div class="grp"><h2>Personal details</h2>'+
   '<div class="fld"><label for="pName">Name<em>*</em></label><input class="in" id="pName" value="'+esc(u.name)+'" autocomplete="name"></div>'+
   '<div class="fld"><label for="pEmail">Email<em>*</em></label><input class="in" id="pEmail" type="email" value="'+esc(u.email)+'" autocomplete="email"'+(AUTH_PROVIDER==="firebase"?' readonly title="Your login email"':'')+'>'+(AUTH_PROVIDER==="firebase"?'<span class="hint">This is your login email.</span>':'')+'</div>'+
   '<div class="f2b"><div class="fld"><label for="pGender">Gender</label><select class="in" id="pGender"><option value="">Select</option>'+["Female","Male","Non-binary","Prefer not to say"].map(function(g){return '<option'+(u.gender===g?' selected':'')+'>'+g+'</option>'}).join("")+'</select></div>'+
   '<div class="fld"><label for="pPhone">Phone</label><input class="in" id="pPhone" type="tel" value="'+esc(u.phone)+'" autocomplete="tel" placeholder="Optional"></div></div></div>'+
   '<button class="save">Save changes</button><div class="err" id="pErr"></div>'+
   '<div class="acctrow"><button type="button" class="linkbtn out" id="outBtn">'+ion("logout",18)+'Log out</button><button type="button" class="linkbtn red" id="delBtn">Delete account</button></div><div id="delBox"></div></form>');
}
function bindProfile(){
  $("#pForm").addEventListener("submit",function(e){e.preventDefault();var u=me();
    var n=$("#pName").value.trim(),em=$("#pEmail").value.trim().toLowerCase(),st=$("#pStart").value.trim();
    if(!n||!/^\S+@\S+\.\S+$/.test(em)){$("#pErr").textContent="Add your name and a valid email.";return}
    if(!st){$("#pErr").textContent="Add where you’re staying so we can plan routes from there.";$("#pStart").focus();return}
    if(em!==u.email&&users[em]){$("#pErr").textContent="Another account already uses that email.";return}
    $("#pErr").textContent="";
    u.name=n;u.gender=$("#pGender").value;u.phone=$("#pPhone").value.trim();u.start=st;
    if(em!==u.email){delete users[u.email];u.email=em;users[em]=u;session=em;save("session",session)}
    persist(u).then(function(){toast("Profile saved")});route();
  });
  $("#pPhoto").onchange=function(){var f=this.files&&this.files[0];if(!f)return;var r=new FileReader();
    r.onload=function(){var img=new Image();img.onload=function(){var s=240,c=document.createElement("canvas");c.width=c.height=s;var k=Math.max(s/img.width,s/img.height),w=img.width*k,h=img.height*k;c.getContext("2d").drawImage(img,(s-w)/2,(s-h)/2,w,h);
      var u=me();u.photo=c.toDataURL("image/jpeg",.85);persist(u).then(function(){toast("Photo updated")});route()};img.src=r.result};r.readAsDataURL(f)};
  if($("#pRm"))$("#pRm").onclick=function(){var u=me();u.photo="";persist(u);route()};
  $("#outBtn").onclick=logout;
  $("#delBtn").onclick=function(){$("#delBox").innerHTML='<div class="confirm">Delete your account and saved itinerary? This can’t be undone.<div class="row"><button type="button" class="sbtn red" id="delYes">Delete account</button><button type="button" class="sbtn plain" id="delNo">Cancel</button></div></div>';
    $("#delYes").onclick=async function(){var em=session,cu=fb()&&fb().currentUser;
      if(cu){try{if(db())await db().collection("users").doc(cu.uid).delete();await cu.delete()}catch(e){
        if(e&&e.code==="auth/requires-recent-login"){$("#delBox").innerHTML='<p class="err">For security, log out and log back in, then delete your account.</p>';return}
        $("#delBox").innerHTML='<p class="err">Couldn’t delete the account. Try again in a moment.</p>';return}}
      await AUTH.signOut();delete users[em];save("users",users);toast("Account deleted");go("")};
    $("#delNo").onclick=function(){$("#delBox").innerHTML=""}};
}
async function logout(){await AUTH.signOut();toast("Logged out");go("")}

var lastRoute=null;
function savedPlaces(){return favs().map(function(n){for(var i=0;i<DATA.rec.length;i++)if(DATA.rec[i].n===n)return DATA.rec[i];return null}).filter(Boolean)}
function itinPage(){
  var u=me(),list=savedPlaces();
  var cards=list.length?'<div class="ilist" id="ilist">'+list.map(function(r){return '<div class="ic2">'+(r.i?'<img src="'+r.i+'" alt="" loading="lazy">':'')+'<div class="tx"><div class="cat">'+esc(r.c)+'</div><b>'+esc(r.n)+'</b><span class="addr">'+I.pin+esc(r.a)+'</span></div><button class="heart on" data-unfav="'+esc(r.n)+'" aria-label="Remove '+esc(r.n)+'" title="Remove from itinerary">'+I.heart+'</button></div>'}).join("")+'</div>'
     :'<p class="iempty">No saved places yet.<br>Tap the heart on any spot in <a href="#recommend">Recommend</a> to add it here.</p>';
  var ready=list.length&&u.start;
  return shell('<div class="panel">'+tabs("i")+
    '<div class="startbox"><i>'+I.pin+'</i><div><small>Starting location</small><b>'+(u.start?esc(u.start):'Not set yet')+'</b></div><a href="#profile">'+(u.start?'Edit':'Add')+'</a></div>'+
    '<div class="ihead"><h2>Saved places'+(list.length?' ('+list.length+')':'')+'</h2>'+(list.length?'<a href="#recommend">+ Add more</a>':'')+'</div>'+cards+
    '<button class="findbtn" id="findBtn"'+(ready?'':' disabled')+'>'+I.bus+'<span>Find best route</span></button>'+
    (!u.start&&list.length?'<p class="err">Add your starting location in Profile to plan a route.</p>':'')+
    '<div class="route" id="route">'+(lastRoute&&lastRoute.key===routeKey(list,u)?lastRoute.html:'')+'</div></div>');
}
function routeKey(list,u){return list.map(function(r){return r.n}).join("|")+"@"+u.start}
function fmtRoute(txt){
  var blocks=[],cur=null;
  txt.split(/\n/).forEach(function(line){line=line.trim();if(!line)return;
    var h=line.match(/^(\d+)\.\s*(.*)$/);
    if(h){cur={n:h[1],h:h[2],b:[]};blocks.push(cur)}else if(cur){cur.b.push(line.replace(/^[-•*]\s*/,""))}});
  function inl(s){return esc(s).replace(/\*\*(.+?)\*\*/g,"<b>$1</b>")}
  if(!blocks.length)return '<h2>Travel Route</h2><p style="font-size:14px">'+inl(txt)+'</p>';
  return '<h2>Travel Route</h2><ol>'+blocks.map(function(b){return '<li><span class="n">'+b.n+'</span><div class="h">'+inl(b.h)+'</div>'+b.b.map(function(x){return '<p>'+inl(x)+'</p>'}).join("")+'</li>'}).join("")+'</ol>';
}
async function askRoute(user,parts){
  if(ROUTE.provider==="openai"){
    if(!ROUTE.endpoint)throw {code:"no_worker"};
    var r=await fetch(ROUTE.endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(parts)});
    if(!r.ok)throw new Error("route_failed");var j=await r.json();return j.route||"";
  }
  var sample=window.claude&&await window.claude.use("sample");
  if(!sample)throw {code:"not_granted"};
  var out=await sample(ROUTE_PROMPT+"\n\n"+user+"\n\nReply with only the numbered route in the format above.",{modelTier:"default",cache:false});
  return out.text;
}
function bindItin(){
  var il=$("#ilist");
  if(il)il.addEventListener("click",function(e){var b=e.target.closest("[data-unfav]");if(!b)return;toggleFav(b.dataset.unfav);toast("Removed from your itinerary");route()});
  var fbtn=$("#findBtn");
  fbtn.onclick=async function(){
    var u=me(),list=savedPlaces();
    if(!list.length||!u.start)return;
    fbtn.disabled=true;fbtn.innerHTML='<span class="spin"></span><span>Finding the best route…</span>';
    var user="name: "+list.map(function(r){return r.n}).join(", ")+" address: "+list.map(function(r){return r.a}).join(", ")+" starting: "+u.start;
    try{
      var txt=await askRoute(user,{name:list.map(function(r){return r.n}).join(", "),address:list.map(function(r){return r.a}).join(", "),starting:u.start});
      var html=fmtRoute(txt);lastRoute={key:routeKey(list,u),html:html};
      var box=$("#route");if(box)box.innerHTML=html;
    }catch(err){
      var box2=$("#route");
      if(box2)box2.innerHTML='<p class="err">'+(err&&err.code==="no_worker"?"The route finder isn’t connected yet. Add your Worker URL to ROUTE_WORKER_URL.":err&&err.code==="not_granted"?"Route finding needs permission. Allow it from the page’s Permissions menu, then try again.":err&&err.code==="rate_limited"?"Too many route requests right now. Wait a minute and try again.":"Couldn’t find a route. Try again in a moment.")+'</p>';
    }
    if(document.body.contains(fbtn)){fbtn.disabled=false;fbtn.innerHTML=I.bus+'<span>Find best route</span>'}
  };
}

/* ---------- router ---------- */
var ROUTES={"":[home],about:[about],recommend:[recPage,bindRec],resources:[resPage],reports:[repPage],contact:[contactPage,bindContact],login:[loginPage,bindLogin],signup:[signupPage,bindSignup],profile:[profilePage,bindProfile,1],itinerary:[itinPage,bindItin,1]};
var TITLES={"":"SEOULMATE · Plan Korea like a local",about:"About · SEOULMATE",recommend:"Recommendations · SEOULMATE",resources:"Resources · SEOULMATE",reports:"Analysis Reports · SEOULMATE",contact:"Contact · SEOULMATE",login:"Log in · SEOULMATE",signup:"Sign up · SEOULMATE",profile:"Profile · SEOULMATE",itinerary:"Itinerary · SEOULMATE"};
/* Hosted build: clean URLs like /about (needs <base data-spa>). Preview: #about. */
var BASE_EL=document.querySelector("base[data-spa]");
var PATH_MODE=!!BASE_EL;
var BASE_PATH=PATH_MODE?new URL(BASE_EL.href).pathname:"/";
function current(){
  if(!PATH_MODE)return location.hash.replace("#","");
  var p=location.pathname;if(p.indexOf(BASE_PATH)===0)p=p.slice(BASE_PATH.length);
  return p.replace(/\/?index\.html$/,"").replace(/^\/+|\/+$/g,"");
}
function hrefFor(r){return PATH_MODE?(BASE_PATH+(r?r:"")):"#"+r}
function go(r,replace){
  if(!PATH_MODE){location.hash="#"+r;return}
  var url=hrefFor(r);
  if(replace)history.replaceState({},"",url);else history.pushState({},"",url);
  route();
}
function fixLinks(root){
  if(!PATH_MODE)return;
  [].forEach.call((root||document).querySelectorAll('a[href^="#"]'),function(a){
    var r=a.getAttribute("href").slice(1);if(r in ROUTES)a.setAttribute("href",hrefFor(r));
  });
}
function route(){
  var h=current();
  if(PATH_MODE&&location.hash&&(location.hash.slice(1) in ROUTES)){go(location.hash.slice(1),true);return}
  if(!ROUTES[h])h="";
  if(ROUTES[h][2]&&!me()){go("login",true);return}
  if((h==="login"||h==="signup")&&me()){go("profile",true);return}
  var r=ROUTES[h];$("#app").innerHTML=r[0]();fixLinks($("#app"));if(r[1])r[1]();
  document.title=TITLES[h]||TITLES[""];
  [].forEach.call(document.querySelectorAll("#nav a"),function(a){a.classList.toggle("on",a.getAttribute("href")===hrefFor(h)&&h!=="")});
  if($("#mnav").classList.contains("open"))setMenu(false);
  [].forEach.call(document.querySelectorAll("#mnav .l"),function(a){a.classList.toggle("on",a.getAttribute("href")===hrefFor(h)&&h!=="")});
  window.scrollTo(0,0);
}
document.addEventListener("click",function(e){var t=e.target.closest&&e.target.closest(".tile");if(t){RS.cat=t.dataset.cat;RS.q="";RS.rain=false;RS.shown=24}},true);
if(PATH_MODE){
  window.addEventListener("popstate",route);
  document.addEventListener("click",function(e){
    if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
    var a=e.target.closest("a[href]");if(!a||a.target==="_blank")return;
    var u=new URL(a.href,location.href);if(u.origin!==location.origin||u.pathname.indexOf(BASE_PATH)!==0)return;
    var r=u.pathname.slice(BASE_PATH.length).replace(/^\/+|\/+$/g,"");
    if(!(r in ROUTES))return;
    e.preventDefault();go(r);
  });
}else window.addEventListener("hashchange",route);
document.addEventListener("click",function(e){
  var t=e.target.closest(".tile");
  var h=e.target.closest("[data-fav]");if(h){var on=toggleFav(h.dataset.fav);if(me()){h.classList.toggle("on",on);toast(on?"Added to your itinerary":"Removed from your itinerary")}}
  var c=e.target.closest("[data-rep]");if(c)openReport(REPORTS[+c.dataset.rep]);
  if(e.target.closest('a[href="#recommend"]')&&!t&&!e.target.closest(".tile")){/* keep filters */}
});
document.addEventListener("keydown",function(e){
  if(e.key==="Escape"&&!$("#modal").hidden)closeReport();
  if(e.key==="Escape"&&$("#mnav").classList.contains("open")){setMenu(false);$("#menuBtn").focus()}
  var c=e.target.closest&&e.target.closest("[data-rep]");if(c&&(e.key==="Enter"||e.key===" ")){e.preventDefault();openReport(REPORTS[+c.dataset.rep])}
});
$("#mClose").onclick=closeReport;
$("#modal").addEventListener("click",function(e){if(e.target===this)closeReport()});
function setMenu(o){var m=$("#mnav");m.classList.toggle("open",o);m.setAttribute("aria-hidden",!o);$("#mscrim").hidden=!o;document.body.classList.toggle("menu-open",o);$("#menuBtn").setAttribute("aria-expanded",o);if(o)$("#mClose2").focus()}
$("#menuBtn").onclick=function(){setMenu(true)};
$("#mClose2").onclick=function(){setMenu(false);$("#menuBtn").focus()};
$("#mscrim").onclick=function(){setMenu(false)};
$("#mnav").addEventListener("click",function(e){if(e.target.closest("a"))setMenu(false)});
window.addEventListener("resize",function(){if(window.innerWidth>820&&$("#mnav").classList.contains("open"))setMenu(false)});
renderAuth();fixLinks(document);route();
